package com.autocare.platform.order;

import com.autocare.platform.common.write.WriteIntegrityService;
import com.autocare.platform.gateway.identity.*;
import com.autocare.platform.vehicle.VehicleOwner;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.nio.file.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.core.io.FileSystemResource;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.springframework.jdbc.datasource.init.ScriptUtils;
import org.springframework.web.server.ResponseStatusException;
import org.testcontainers.containers.MySQLContainer;
import org.testcontainers.junit.jupiter.*;
import static org.junit.jupiter.api.Assertions.*;

@Testcontainers class JdbcCommunityQuestionsTest {
    static com.zaxxer.hikari.HikariDataSource schemaPool;
    @AfterAll static void closeSchemaPool(){if(schemaPool!=null){schemaPool.close();schemaPool=null;}}
 @Container static MySQLContainer<?> mysql=new MySQLContainer<>("mysql:8.0").withCommand("--log-bin-trust-function-creators=1");
 static JdbcTemplate jdbc;ReservationStore db;JdbcReservationsTest.Time clock;CommunityQuestions questions;CommunityQuestionPolicies policies;
 VehicleOwner owner,peer;OperatorActor manager,first,second;ObjectMapper json=new ObjectMapper();
 @BeforeAll static void schema()throws Exception{var ds=com.autocare.platform.TestMysqlDataSource.open(mysql);schemaPool=ds;jdbc=new JdbcTemplate(ds);try(var c=ds.getConnection();var paths=Files.list(Path.of("..","docs","sql","migrations"))){for(var p:paths.filter(p->p.toString().endsWith(".sql")).sorted().toList())ScriptUtils.executeSqlScript(c,new FileSystemResource(p));ScriptUtils.executeSqlScript(c,new FileSystemResource(Path.of("..","docs","sql","migrations","V058__private_community_questions.sql")));}assertEquals(134,jdbc.queryForObject("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_type='BASE TABLE'",Integer.class));}
 @BeforeEach void setup(){jdbc.execute("DROP TRIGGER IF EXISTS reject_community_write");for(String t:List.of("community_qa_case_event","community_qa_message","community_qa_case","community_qa_service_policy","audit_log","idempotency_record","auth_session","operator_account","vehicle","model","series","brand","user"))jdbc.update("DELETE FROM `"+t+"`");
  clock=new JdbcReservationsTest.Time();var tx=new DataSourceTransactionManager(jdbc.getDataSource());db=new ReservationStore(jdbc,json,new WriteIntegrityService(jdbc,json,tx),clock,tx);policies=new CommunityQuestionPolicies(db,new OperatorIdentity(jdbc,null,tx));questions=new CommunityQuestions(db,policies);
  jdbc.update("INSERT INTO `user`(id,openid,status) VALUES(1,'synthetic-community-a',1),(2,'synthetic-community-b',1)");
  jdbc.update("INSERT INTO brand(id,name,status) VALUES(1,'合成品牌',1)");jdbc.update("INSERT INTO series(id,brand_id,name,status) VALUES(1,1,'合成车系',1)");jdbc.update("INSERT INTO model(id,series_id,year,config_name,status) VALUES(1,1,'2026','合成配置',1)");jdbc.update("INSERT INTO vehicle(id,user_id,model_id,plate_no,vin) VALUES(1,1,1,'private-plate','private-vin'),(2,2,1,'peer-plate','peer-vin')");
  jdbc.update("INSERT INTO operator_account(id,account,password_hash,phone,can_community_answer,can_community_manage,can_diagnose,can_diagnose_manage,can_community_curate) VALUES(1,'synthetic-community-manager','unused','13800000001',0,1,1,1,1),(2,'synthetic-community-first','unused','13800000002',1,0,0,0,0),(3,'synthetic-community-second','unused','13800000003',1,0,0,0,0)");
  owner=user(1);peer=user(2);manager=operator(1);first=operator(2);second=operator(3);
 }
 @AfterEach void cleanup(){jdbc.execute("DROP TRIGGER IF EXISTS reject_community_write");}
 String key(){return UUID.randomUUID().toString();}
 String session(long id,boolean op){String s=key();jdbc.update("INSERT INTO auth_session(id,subject_type,subject_id,role,app_id,refresh_hash,expires_at) VALUES(?,?,?,?,?,?,DATE_ADD(UTC_TIMESTAMP(),INTERVAL 1 HOUR))",s,op?"operator_account":"user",id,op?"OPERATOR":"OWNER",op?OperatorActor.APP:"test",key());return s;}
 VehicleOwner user(long id){return new VehicleOwner(id,session(id,false),Instant.now().plusSeconds(3600));}
 OperatorActor operator(long id){return new OperatorActor(id,session(id,true),Instant.now().plusSeconds(3600));}
 int code(Runnable r){try{r.run();return 200;}catch(ResponseStatusException e){return e.getStatusCode().value();}}
 int count(String t){return jdbc.queryForObject("SELECT COUNT(*) FROM `"+t+"`",Integer.class);}
 ObjectNode config(String mode){return json.createObjectNode().put("mode",mode).put("source_note","仅运营可见的合成受理来源").put("valid_from",clock.value.minusSeconds(60).toString()).put("valid_to",clock.value.plusSeconds(3600).toString());}
 ObjectNode state(long revision,String status){return json.createObjectNode().put("expected_revision",revision).put("status",status);}
 long configure(String mode){long id=policies.save(manager,null,key(),config(mode)).path("data").path("id").asLong();policies.status(manager,id,key(),state(1,"PUBLISHED"));return id;}
 ObjectNode question(long policy){return json.createObjectNode().put("vehicle_id",1).put("policy_id",policy).put("policy_revision",2).put("category","FAULT").put("message","本人主动提交的私有问题").put("consent",true);}
 long submit(long p){return questions.create(owner,key(),question(p)).path("data").path("case_id").asLong();}
 ObjectNode assign(long rev,long op){return json.createObjectNode().put("expected_revision",rev).put("operator_id",op);}
 ObjectNode message(long rev,String text){return json.createObjectNode().put("expected_revision",rev).put("message",text);}
 ObjectNode follow(long rev,long policy){return message(rev,"主动补充").put("policy_id",policy).put("policy_revision",2).put("consent",true);}
 @Test void independentPermissionsAndUnconfiguredAdmissionDenyNewQuestions(){assertEquals("UNKNOWN",policies.current(owner).get("state"));assertEquals(false,policies.current(owner).get("accepting"));assertEquals(403,code(()->policies.list(first,1)));assertEquals(403,code(()->questions.list(manager,false,1)));assertEquals(403,code(()->questions.list(first,true,1)));assertEquals(409,code(()->questions.create(owner,key(),question(1))));assertEquals(0,count("community_qa_case"));assertEquals(0,count("diagnosis_case"));}
 @Test void effectiveWindowModesAndHandlersAreCurrent(){long p=configure("LEAVE_MESSAGE");assertEquals(true,policies.current(owner).get("accepting"));assertFalse(db.json(policies.current(owner)).contains("source_note"));submit(p);clock.value=clock.value.plusSeconds(3600);assertEquals("EXPIRED",policies.current(owner).get("state"));assertEquals(409,code(()->questions.create(owner,key(),question(p))));policies.status(manager,p,key(),state(2,"STOPPED"));long paused=configure("PAUSED");assertEquals("PAUSED",policies.current(owner).get("state"));assertEquals(409,code(()->questions.create(owner,key(),question(paused))));policies.status(manager,paused,key(),state(2,"STOPPED"));configure("AVAILABLE");jdbc.update("UPDATE operator_account SET can_community_answer=0");assertEquals("SOURCE_UNAVAILABLE",policies.current(owner).get("state"));}
 @Test void policyDraftCasFreezeAndPermanentCreationReceipt(){String k=key();var b=config("AVAILABLE");var original=policies.save(manager,null,k,b);long p=original.path("data").path("id").asLong();var updated=b.deepCopy().put("expected_revision",1).put("mode","LEAVE_MESSAGE");policies.save(manager,p,key(),updated);assertEquals(409,code(()->policies.save(manager,p,key(),updated)));policies.status(manager,p,key(),state(2,"PUBLISHED"));assertEquals(409,code(()->policies.save(manager,p,key(),updated.put("expected_revision",3))));policies.status(manager,p,key(),state(3,"STOPPED"));clock.value=clock.value.plusSeconds(4000);expireKeys();assertEquals(original.path("data"),policies.save(manager,null,k,b).path("data"));assertEquals(1,count("community_qa_service_policy"));assertEquals(400,code(()->policies.save(manager,null,k,b.deepCopy().put("source_note","changed source"))));assertEquals(409,code(()->policies.status(manager,p,key(),state(4,"PUBLISHED"))));}
 void expireKeys(){jdbc.update("UPDATE idempotency_record SET expires_at=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 1 DAY)");}
 @Test void questionCreationReceiptSurvivesTransferPolicyStopAndGenericExpiry(){long p=configure("AVAILABLE");String k=key();var b=question(p);var original=questions.create(owner,k,b);long id=original.path("data").path("case_id").asLong();questions.assign(manager,id,key(),assign(1,2));policies.status(manager,p,key(),state(2,"STOPPED"));jdbc.update("UPDATE vehicle SET user_id=2 WHERE id=1");expireKeys();assertEquals(original.path("data"),questions.create(owner,k,b).path("data"));assertEquals(1,count("community_qa_case"));assertEquals(1,count("community_qa_message"));assertEquals(400,code(()->questions.create(owner,k,b.deepCopy().put("message","different"))));jdbc.update("UPDATE auth_session SET revoked_at=UTC_TIMESTAMP() WHERE id=?",owner.session());assertEquals(401,code(()->questions.create(owner,k,b)));}
 @Test void onlyOriginalOwnerAndCurrentAssigneeCanReadContent(){long id=submit(configure("AVAILABLE"));assertEquals(403,code(()->questions.detail(manager,id,1)));assertEquals(404,code(()->questions.detail(first,id,1)));assertEquals(404,code(()->questions.detail(peer,id,1)));var queue=json.valueToTree(questions.list(manager,true,1));assertEquals(Set.of("case_id","revision","status","created_at","updated_at","assigned_operator_id"),json.convertValue(queue.path("items").get(0),Map.class).keySet());assertFalse(queue.toString().contains("主动"));assertFalse(queue.toString().contains("vehicle"));questions.assign(manager,id,key(),assign(1,2));var detail=json.valueToTree(questions.detail(first,id,1));assertEquals("FAULT",detail.path("category").asText());for(String hidden:List.of("owner_id","vehicle_id","sender_id","vin","plate_no","source_note","submission_key","admission_snapshot"))assertFalse(detail.toString().contains("\""+hidden+"\""),hidden);assertEquals("本人主动提交的私有问题",detail.path("messages").path("items").get(0).path("body").asText());assertFalse(jdbc.queryForObject("SELECT after_state FROM audit_log WHERE action='COMMUNITY_QUESTION_CREATE'",String.class).contains("主动"));}
 @Test void reassignAndRevokePreventFormerHandlerReadingEvenOldReceipt(){long p=configure("AVAILABLE"),id=submit(p);questions.assign(manager,id,key(),assign(1,2));String k=key();var b=message(2,"第一位答复");questions.write(first,id,"reply",k,b);questions.assign(manager,id,key(),assign(3,3));assertEquals(404,code(()->questions.detail(first,id,1)));assertEquals(404,code(()->questions.write(first,id,"reply",k,b)));questions.write(second,id,"reply",key(),message(4,"第二位答复"));jdbc.update("UPDATE operator_account SET can_community_answer=0 WHERE id=3");assertEquals(403,code(()->questions.detail(second,id,1)));questions.write(owner,id,"message",key(),follow(5,p));assertEquals("WAITING",questions.row(id,false).get("status"));assertNull(questions.row(id,false).get("assigned_operator_id"));}
 @Test void stoppedAdmissionBlocksNewInputButExistingReplyAndCloseRemainUsable(){long p=configure("AVAILABLE"),id=submit(p);questions.assign(manager,id,key(),assign(1,2));policies.status(manager,p,key(),state(2,"STOPPED"));assertEquals(409,code(()->questions.create(owner,key(),question(p))));assertEquals(409,code(()->questions.write(owner,id,"message",key(),follow(2,p))));questions.write(first,id,"reply",key(),message(2,"处理已存在的问题"));assertEquals(403,code(()->questions.write(manager,id,"close",key(),json.createObjectNode().put("expected_revision",3))));questions.write(owner,id,"close",key(),json.createObjectNode().put("expected_revision",3));assertEquals(409,code(()->questions.write(first,id,"reply",key(),message(4,"关闭后禁止"))));assertEquals(4,count("community_qa_case_event"));}
 @Test void oldOwnerHistoryDoesNotTransferWithVehicleAndCatalogIsRechecked(){long p=configure("AVAILABLE"),id=submit(p);jdbc.update("UPDATE model SET status=0 WHERE id=1");assertEquals(409,code(()->questions.write(owner,id,"message",key(),follow(1,p))));assertNotNull(questions.detail(owner,id,1));jdbc.update("UPDATE model SET status=1 WHERE id=1");assertEquals(404,code(()->questions.create(peer,key(),question(p))));jdbc.update("UPDATE vehicle SET user_id=2 WHERE id=1");assertEquals(404,code(()->questions.write(owner,id,"message",key(),follow(1,p))));assertNotNull(questions.detail(owner,id,1));assertEquals(404,code(()->questions.detail(peer,id,1)));assertEquals(0L,questions.list(peer,false,1).get("total"));}
 @Test void eventFailureRollsBackQuestionAndPermanentIntent(){long p=configure("AVAILABLE");String k=key();jdbc.execute("CREATE TRIGGER reject_community_write BEFORE INSERT ON community_qa_case_event FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='synthetic failure'");assertEquals(503,code(()->questions.create(owner,k,question(p))));assertEquals(0,count("community_qa_case"));assertEquals(0,count("community_qa_message"));jdbc.execute("DROP TRIGGER reject_community_write");assertTrue(questions.create(owner,k,question(p)).path("data").path("case_id").asLong()>0);}
 @Test void auditFailureRollsBackReplyAndVersion(){long id=submit(configure("AVAILABLE"));questions.assign(manager,id,key(),assign(1,2));String k=key();jdbc.execute("CREATE TRIGGER reject_community_write BEFORE INSERT ON audit_log FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='synthetic failure'");assertEquals(503,code(()->questions.write(first,id,"reply",k,message(2,"原键重试"))));assertEquals(1,count("community_qa_message"));assertEquals(2L,((Number)questions.row(id,false).get("revision")).longValue());jdbc.execute("DROP TRIGGER reject_community_write");questions.write(first,id,"reply",k,message(2,"原键重试"));assertEquals(2,count("community_qa_message"));}
 @Test void readsNeverAddEventsOrReceiptAndPaginationHasNoContentLeak(){long p=configure("AVAILABLE"),id=submit(p);int audit=count("audit_log"),keys=count("idempotency_record"),events=count("community_qa_case_event");assertEquals(1L,questions.list(owner,false,1).get("total"));assertTrue(((List<?>)questions.list(owner,false,2).get("items")).isEmpty());assertTrue(((List<?>)((Map<?,?>)questions.detail(owner,id,2).get("messages")).get("items")).isEmpty());policies.current(owner);policies.handlers(manager,1);assertEquals(audit,count("audit_log"));assertEquals(keys,count("idempotency_record"));assertEquals(events,count("community_qa_case_event"));}
 @Test void strictInputRejectsExtraFieldsWrongTypesAndUnconfirmedOrOversizeText(){long p=configure("AVAILABLE");for(String raw:List.of(question(p).put("consent",false).toString(),question(p).put("category","OTHER").toString(),question(p).put("archive_id",1).toString(),question(p).put("message","a".repeat(2001)).toString(),question(p).put("message"," ").toString(),question(p).put("vehicle_id",1.0).toString(),question(p)+"{}"))assertThrows(ResponseStatusException.class,()->CommunityQuestions.input(raw,"create"));assertThrows(ResponseStatusException.class,()->CommunityQuestions.input("{\"expected_revision\":1,\"expected_revision\":2}","close"));assertNotNull(CommunityQuestions.input(question(p).toString(),"create"));}
 @Test void twoAssignmentsHaveOneCasWinner()throws Exception{long id=submit(configure("AVAILABLE"));var pool=Executors.newFixedThreadPool(2);var gate=new CountDownLatch(1);try{var x=pool.submit(()->{gate.await();return code(()->questions.assign(manager,id,key(),assign(1,2)));});var y=pool.submit(()->{gate.await();return code(()->questions.assign(manager,id,key(),assign(1,3)));});gate.countDown();var result=new ArrayList<>(List.of(x.get(30,TimeUnit.SECONDS),y.get(30,TimeUnit.SECONDS)));Collections.sort(result);assertEquals(List.of(200,409),result);assertEquals(2,count("community_qa_case_event"));}finally{pool.shutdownNow();}}
 @Test void simultaneousCreationWithSameKeyProducesOneOriginalQuestion()throws Exception{long p=configure("AVAILABLE");String k=key();var pool=Executors.newFixedThreadPool(2);var gate=new CountDownLatch(1);try{var x=pool.submit(()->{gate.await();return questions.create(owner,k,question(p));});var y=pool.submit(()->{gate.await();return questions.create(owner,k,question(p));});gate.countDown();assertEquals(x.get(30,TimeUnit.SECONDS),y.get(30,TimeUnit.SECONDS));assertEquals(1,count("community_qa_case"));assertEquals(1,count("community_qa_message"));}finally{pool.shutdownNow();}}
 @Test void distinctManagersCannotPublishTwoPolicies()throws Exception{jdbc.update("UPDATE operator_account SET can_community_manage=1 WHERE id=3");long p=policies.save(manager,null,key(),config("AVAILABLE")).path("data").path("id").asLong(),q=policies.save(second,null,key(),config("LEAVE_MESSAGE")).path("data").path("id").asLong();var pool=Executors.newFixedThreadPool(2);var gate=new CountDownLatch(1);try{var x=pool.submit(()->{gate.await();return code(()->policies.status(manager,p,key(),state(1,"PUBLISHED")));});var y=pool.submit(()->{gate.await();return code(()->policies.status(second,q,key(),state(1,"PUBLISHED")));});gate.countDown();var result=new ArrayList<>(List.of(x.get(30,TimeUnit.SECONDS),y.get(30,TimeUnit.SECONDS)));Collections.sort(result);assertEquals(List.of(200,409),result);}finally{pool.shutdownNow();}}
 @Test void realControlWaitRechecksExpirationBeforeAcceptingNewText()throws Exception{long p=configure("AVAILABLE");var pool=Executors.newSingleThreadExecutor();try(var c=jdbc.getDataSource().getConnection()){c.setAutoCommit(false);try(var s=c.createStatement()){s.executeQuery("SELECT id FROM community_qa_control WHERE id=1 FOR UPDATE").close();}var f=pool.submit(()->code(()->questions.create(owner,key(),question(p))));var monitor=new JdbcTemplate(new DriverManagerDataSource(mysql.getJdbcUrl(),"root",mysql.getPassword()));boolean waiting=false;long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(8);while(System.nanoTime()<deadline){if(monitor.queryForList("SELECT trx_state,trx_query FROM information_schema.innodb_trx").stream().anyMatch(r->"LOCK WAIT".equals(r.get("trx_state"))&&String.valueOf(r.get("trx_query")).contains("community_qa_control"))){waiting=true;break;}if(f.isDone())break;Thread.sleep(100);}assertTrue(waiting,"must observe actual control lock wait");clock.value=clock.value.plusSeconds(3600);c.commit();assertEquals(409,f.get(30,TimeUnit.SECONDS));assertEquals(0,count("community_qa_case"));}finally{pool.shutdownNow();}}
}
